def run(ds: DataSet, out: Path) -> None:
    (out / "events").mkdir(parents=True, exist_ok=True)
    docs, errors = [], []
    for uid in ds.uids():
        try:
            doc = event_doc(ds.event(uid), ds.window)
        except AgendaError as e:
            errors.append({"event": uid, "error": f"{type(e).__name__}: {e}"})
            continue
